/**
 * Soucet objednavky v halerich, BEZ slevy, v mene objednavky.
 */
function order_total($orderId)
{
    global $db;
    legacy_db();
    $row = $db->one("SELECT SUM(quantity * unit_price_amount_in_cents) AS total FROM order_items WHERE order_id = '" . $orderId . "'");
